WITH ProductsBySupplier AS (SELECT supplier_id, ROUND(AVG(cost), 2) AS avg_cost, ROUND((100 * SUM(CASE WHEN category = 'Electronics' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_electronics FROM products GROUP BY supplier_id) SELECT s.id, s.rating, s.country, P.avg_cost, P.pct_electronics FROM suppliers s LEFT JOIN ProductsBySupplier P ON s.id = P.supplier_id ORDER BY pct_electronics DESC;
